let filterApprovalForAll (contract: Contract) (fromBlock: BlockParameter) (toBlock: BlockParameter) =
    let filter = contract.GetEventBySignature("0x17307eab39ab6107e8899845ad3d59bd9653f200f220920489ca2b5937696c31").CreateFilterInput(fromBlock, toBlock)
    filter

let decodeApprovalForAllEvent (contract: Contract) (log: FilterLog) : ApprovalForAllEvent =
    let decoded = contract.GetEventBySignature("0x17307eab39ab6107e8899845ad3d59bd9653f200f220920489ca2b5937696c31").DecodeAllEventsForEvent<ApprovalForAllEvent>([| log |])
    if decoded.Count <> 1 then invalidArg "log" "Log does not match event"
    decoded.[0].Event

let queryApprovalForAll (contract: Contract) (filter: NewFilterInput) =
    if isNull filter || isNull filter.Address || not (filter.Address |> Array.exists (fun address -> String.Equals(address, contract.Address, StringComparison.OrdinalIgnoreCase))) then invalidArg "filter" "Filter must include this contract address"
    task {
        let! logs = contract.Eth.Filters.GetLogs.SendRequestAsync(filter)
        let result = ResizeArray<EventLog<ApprovalForAllEvent>>()
        let event = contract.GetEventBySignature("0x17307eab39ab6107e8899845ad3d59bd9653f200f220920489ca2b5937696c31")
        for log in logs do
            if String.Equals(log.Address, contract.Address, StringComparison.OrdinalIgnoreCase) && event.IsLogForEvent(log) then
                result.Add(EventLog<ApprovalForAllEvent>(decodeApprovalForAllEvent contract log, log))
        return result
    }

