let decodeNotAuthorizedError (data: string) : NotAuthorizedError =
    if isNull data || not (data.StartsWith("0xea8e4eb5", StringComparison.OrdinalIgnoreCase)) then invalidArg "data" "Custom error selector mismatch"
    if data.Length <> 10 then invalidArg "data" "Unexpected custom error payload"
    Nethereum.Contracts.Error(typeof<NotAuthorizedError>).DecodeExceptionEncodedData<NotAuthorizedError>(data)

let decodeZeroOwnerError (data: string) : ZeroOwnerError =
    if isNull data || not (data.StartsWith("0x9905827b", StringComparison.OrdinalIgnoreCase)) then invalidArg "data" "Custom error selector mismatch"
    if data.Length <> 10 then invalidArg "data" "Unexpected custom error payload"
    Nethereum.Contracts.Error(typeof<ZeroOwnerError>).DecodeExceptionEncodedData<ZeroOwnerError>(data)

